export function assertTimeZone(timeZone: string): void {
  new Intl.DateTimeFormat("en-US", { timeZone });
}

interface LocalParts {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
}

function localParts(instantMs: number, timeZone: string): LocalParts {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
  }).formatToParts(new Date(instantMs));
  const get = (type: string): number =>
    Number(parts.find((part) => part.type === type)?.value ?? 0);
  return {
    year: get("year"),
    month: get("month"),
    day: get("day"),
    hour: get("hour") % 24,
    minute: get("minute"),
    second: get("second"),
  };
}

/** Zone offset from UTC, in ms, at the given instant. */
function offsetMs(instantMs: number, timeZone: string): number {
  const p = localParts(instantMs, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return asUtc - Math.floor(instantMs / 1000) * 1000;
}

/** The instant at which the zone's wall clock shows the given date and hour. */
function zonedInstant(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number {
  const wall = Date.UTC(year, month - 1, day, hour);
  const first = wall - offsetMs(wall, timeZone);
  const second = wall - offsetMs(first, timeZone);
  if (second === first) return first;
  // Across a transition: prefer the candidate whose wall clock matches.
  const back = localParts(second, timeZone);
  if (back.hour === hour && back.day === day) return second;
  return Math.max(first, second);
}

/** The `YYYY-MM-DD` calendar date of an instant in the given zone. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const p = localParts(parseIso(value).getTime(), timeZone);
  const pad = (n: number, w: number): string => String(n).padStart(w, "0");
  return `${pad(p.year, 4)}-${pad(p.month, 2)}-${pad(p.day, 2)}`;
}

/**
 * The UTC instant at which the zone's calendar day, `daysBefore` days before
 * the one containing `reference`, began.
 */
export function startOfLocalDay(
  reference: Date,
  timeZone: string,
  daysBefore = 0,
): IsoTimestamp {
  const p = localParts(reference.getTime(), timeZone);
  const shifted = new Date(Date.UTC(p.year, p.month - 1, p.day - daysBefore));
  return toIsoTimestamp(
    new Date(
      zonedInstant(
        shifted.getUTCFullYear(),
        shifted.getUTCMonth() + 1,
        shifted.getUTCDate(),
        0,
        timeZone,
      ),
    ),
  );
}

/**
 * True once the calendar day (on the workspace clock) containing `dueAt` has
 * ended. Due dates are whole days: on the day itself nothing is overdue yet.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return parseIso(dueAt).getTime() < Date.parse(startOfLocalDay(reference, timeZone));
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers, ending at the most recent local `digestHour:00`
 * at or before `reference` and starting at the same local hour the previous
 * calendar day (23 or 25 hours across a DST change).
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  const p = localParts(reference.getTime(), timeZone);
  let end = zonedInstant(p.year, p.month, p.day, digestHour, timeZone);
  let day = new Date(Date.UTC(p.year, p.month - 1, p.day));
  if (end > reference.getTime()) {
    day = new Date(day.getTime() - DAY_MS);
    end = zonedInstant(
      day.getUTCFullYear(),
      day.getUTCMonth() + 1,
      day.getUTCDate(),
      digestHour,
      timeZone,
    );
  }
  const prev = new Date(day.getTime() - DAY_MS);
  const start = zonedInstant(
    prev.getUTCFullYear(),
    prev.getUTCMonth() + 1,
    prev.getUTCDate(),
    digestHour,
    timeZone,
  );

  return { start: toIsoTimestamp(new Date(start)), end: toIsoTimestamp(new Date(end)) };
}
