export function startOfLocalDay(
  reference: Date,
  timeZone: string,
  daysBefore = 0,
): IsoTimestamp {
  const p = localParts(reference.getTime(), timeZone);
  const shifted = new Date(Date.UTC(p.year, p.month - 1, p.day - daysBefore));
  return toIsoTimestamp(
    new Date(
      zonedInstant(
        shifted.getUTCFullYear(),
        shifted.getUTCMonth() + 1,
        shifted.getUTCDate(),
